def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    marker = min((v for v in counts if v not in (0, 8, 2)), default=None)
    # Find the rare motif color distinct from the two field colors.
    if marker is None:
        candidates = [(n, v) for v,n in counts.items() if v not in (0, 8) and n < h*w//2]
        if not candidates:
            return [row[:] for row in grid]
        marker = min(candidates)[1]
    positions = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    if not positions:
        return [row[:] for row in grid]
    r0, r1 = min(r for r,c in positions), max(r for r,c in positions)
    c0, c1 = min(c for r,c in positions), max(c for r,c in positions)
    shape = {(r-r0, c-c0) for r,c in positions}
    out = [row[:] for row in grid]
    for r in range(h-(r1-r0)):
        for c in range(w-(c1-c0)):
            if (r,c) == (r0,c0):
                continue
            cells = [(r+dr, c+dc) for dr,dc in shape]
            if all(grid[rr][cc] == 0 for rr,cc in cells):
                for rr,cc in cells:
                    out[rr][cc] = marker
    return out

